wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109802821565663381)
,p_name=>'PE.PROPERTY.BREAK_REPEAT_HEADING_FORMAT.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Balisage HTML pour les en-t\00EAtes r\00E9p\00E9t\00E9s affich\00E9s pour les sections d''\00E9tat. Vous pouvez utiliser <code>#COLUMN_VALUE#</code>, qui est remplac\00E9 par la valeur de la premi\00E8re colonne d''\00E9tat.'),
'</br>',
unistr('En cas d''omission, APEX g\00E9n\00E8re le balisage de ligne HTML par d\00E9faut.')))
,p_version_scn=>2564603
);
