wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109176510954663192)
,p_name=>'PE.PROPERTY.ERROR_MESSAGE.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le texte \00E0 afficher en cas d''\00E9chec de la validation.</p>'),
unistr('<p>Vous pouvez utiliser <code>#LABEL#</code> comme valeur de r\00E9serve pour le libell\00E9 de l''\00E9l\00E9ment associ\00E9 de la page ou <code>#COLUMN_HEADER#</code> pour l''en-t\00EAte de la colonne de r\00E9gion modifiable associ\00E9e. Les valeurs de r\00E9serve ne sont pas prises')
||unistr(' en charge si l''emplacement d''affichage d''erreur est d\00E9fini sur Page d''\00E9v\00E9nement d''erreur.</p>')))
,p_version_scn=>2564488
);
