wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109795303231663379)
,p_name=>'PE.PROPERTY.FIELD_TEMPLATE.COMPONENT_PROPERTY.CLASSIC_REPORT_COLUMN.HELP'
,p_message_language=>'fr'
,p_message_text=>unistr('S\00E9lectionnez le mod\00E8le de champ \00E0 utiliser pour l''affichage du champ de panneau tabulaire. Si aucun mod\00E8le n''est s\00E9lectionn\00E9, le champ est affich\00E9 \00E0 l''aide du libell\00E9 conforme \00E0 l''accessibilit\00E9 par d\00E9faut.')
,p_version_scn=>2564598
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109815174652663385)
,p_name=>'PE.PROPERTY.FIELD_TEMPLATE.COMPONENT_PROPERTY.TABULAR_FORM_COLUMN.HELP'
,p_message_language=>'fr'
,p_message_text=>unistr('S\00E9lectionnez le mod\00E8le de champ \00E0 utiliser pour l''affichage du champ de panneau tabulaire. Si aucun mod\00E8le n''est s\00E9lectionn\00E9, le champ est affich\00E9 \00E0 l''aide du libell\00E9 conforme \00E0 l''accessibilit\00E9 par d\00E9faut.')
,p_version_scn=>2564605
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109187350207663195)
,p_name=>'PE.PROPERTY.FIELD_TEMPLATE.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>S\00E9lectionnez un mod\00E8le de libell\00E9 pour d\00E9finir l''apparence et la mise en page de ce libell\00E9 d''\00E9l\00E9ment.</p>'),
unistr('        <p>Les mod\00E8les de libell\00E9 sont d\00E9finis dans le th\00E8me d''application.'),
unistr('        Lorsqu''un \00E9l\00E9ment est cr\00E9\00E9, le mod\00E8le est automatiquement configur\00E9 sur le mod\00E8le d''\00E9l\00E9ment par d\00E9faut d\00E9fini dans le th\00E8me en cours.</p>'),
unistr('        <p>De nombreux th\00E8mes comprennent des mod\00E8les de libell\00E9 pour l''affichage des libell\00E9s masqu\00E9s, facultatifs et obligatoires.<br>'),
unistr('        Le th\00E8me universel fournit les mod\00E8les de libell\00E9 suivants :'),
'          <dl>',
unistr('            <dt>Masqu\00E9</dt>'),
unistr('              <dd>A utiliser lorsque le libell\00E9 ne doit pas \00EAtre affich\00E9 \00E0 l''\00E9cran. La technologie d''assistance pourra toujours lire le libell\00E9.'),
unistr('              Le libell\00E9 Masqu\00E9 est ignor\00E9 pour les \00E9l\00E9ments Case \00E0 cocher car un libell\00E9 doit \00EAtre affich\00E9 apr\00E8s la case \00E0 cocher.</dd>'),
'            <dt>Facultatif</dt>',
unistr('              <dd>A utiliser pour les \00E9l\00E9ments de panneau facultatifs. Le libell\00E9 sera affich\00E9 sur le c\00F4t\00E9 de l''\00E9l\00E9ment.</dd>'),
'            <dt>Facultatif - Au-dessus</dt>',
unistr('              <dd>A utiliser pour les \00E9l\00E9ments de panneau facultatifs. Le libell\00E9 sera affich\00E9 au-dessus de l''\00E9l\00E9ment.</dd>'),
'            <dt>Facultatif - Flottant</dt>',
unistr('              <dd>A utiliser pour les \00E9l\00E9ments de panneau facultatifs. Le libell\00E9 sera affich\00E9 \00E0 l''int\00E9rieur de l''\00E9l\00E9ment saisi et sera r\00E9duit automatiquement d\00E8s que le champ de saisie contiendra une valeur.</dd>'),
'            <dt>Obligatoire</dt>',
unistr('              <dd>Ce mod\00E8le de libell\00E9 affiche un ast\00E9risque rouge en regard du libell\00E9 et est utilis\00E9 pour les \00E9l\00E9ments de panneau pour lesquels une entr\00E9e utilisateur est requise. Le libell\00E9 sera affich\00E9 sur le c\00F4t\00E9 de l''\00E9l\00E9ment.</dd>'),
'            <dt>Obligatoire - Au-dessus</dt>',
unistr('              <dd>Ce mod\00E8le de libell\00E9 affiche un ast\00E9risque rouge en regard du libell\00E9 et est utilis\00E9 pour les \00E9l\00E9ments de panneau pour lesquels une entr\00E9e utilisateur est requise. Le libell\00E9 sera affich\00E9 au-dessus de l''\00E9l\00E9ment. Les mod\00E8les d''\00E9l\00E9men')
||unistr('t vous permettent de d\00E9finir les attributs d''interface utilisateur dans le cadre d''un th\00E8me et de partager cette d\00E9finition parmi de nombreux \00E9l\00E9ments de page.</dd>'),
'            <dt>Obligatoire - Flottant</dt>',
unistr('              <dd>Ce mod\00E8le de libell\00E9 affiche un ast\00E9risque rouge en regard du libell\00E9 et est utilis\00E9 pour les \00E9l\00E9ments de panneau dans lesquels une saisie de l''utilisateur est requise. Le libell\00E9 est affich\00E9 \00E0 l''int\00E9rieur de l''\00E9l\00E9ment saisi et sera')
||unistr(' r\00E9duit automatiquement d\00E8s que le champ de saisie contiendra une valeur. Les mod\00E8les d''\00E9l\00E9ment vous permettent de d\00E9finir les attributs de l''interface utilisateur dans le cadre d''un th\00E8me et de partager cette d\00E9finition parmi de nombreux \00E9l\00E9ments de')
||' page.</dd>',
'          </dl>',
unistr('          Reportez-vous \00E9galement \00E0 <a rel="noopener noreferrer" target="_blank" href="https://apex.oracle.com/ut">Application \00E9chantillon de th\00E8me universel</a>'),
'        </p>'))
,p_version_scn=>2564490
);
