,p_name=>'PE.PROPERTY.FILTER_OPERATORS.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>S\00E9lectionnez les op\00E9rateurs de filtre dont les utilisateurs finals peuvent se servir pour cette colonne.</p>'),
unistr('        <p>En fonction de la taille de l''ensemble de donn\00E9es et des index de colonne, vous pouvez d\00E9sactiver certains op\00E9rateurs de filtre afin d''\00E9viter tout probl\00E8me de performances pour les utilisateurs finals.'),
unistr('        Certains op\00E9rateurs peuvent entra\00EEner des balayages complets de table au lieu d''utiliser des index de colonne.</p>')))
,p_version_scn=>2564578
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109833999146663391)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.D'
,p_message_language=>'fr'
,p_message_text=>'Contient'
,p_version_scn=>2564610
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109834039691663391)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le filtre renvoie des r\00E9sultats de valeurs de colonne contenant la valeur de filtre.'),
'        &PRODUCT_NAME. utilise <code>column LIKE <strong>%</strong>filtervalue<strong>%</strong></code> dans la clause WHERE.</p>',
unistr('        <p>Remarque : cet op\00E9rateur emp\00EAche l''utilisation de tout index de colonne, ce qui peut entra\00EEner un balayage complet de table.</p>')))
,p_version_scn=>2564610
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109662732846663339)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.CASE_INSENSITIVE.D'
,p_message_language=>'fr'
,p_message_text=>'Sans respect maj/min'
,p_version_scn=>2564578
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109786647117663376)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.CASE_INSENSITIVE.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le filtre renvoie des r\00E9sultats de valeurs de colonne sans prendre en compte les diff\00E9rences de casse de la valeur de colonne et de la valeur de filtre.'),
'        &PRODUCT_NAME. utilise <code>UPPER(column) <em>operator</em> UPPER(filtervalue)</code> dans la clause WHERE.</p>',
unistr('        <p>Remarque : en g\00E9n\00E9ral, l''utilisation de l''op\00E9ration UPPER sur les valeurs de colonne et de filtre emp\00EAche d''utiliser des index de colonne, \00E0 l''exception des index de colonne reposant sur la fonction avec UPPER(<em>column</em>).</p>')))
,p_version_scn=>2564597
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109662614629663338)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.REGEXP.D'
,p_message_language=>'fr'
,p_message_text=>unistr('Expression r\00E9guli\00E8re')
,p_version_scn=>2564578
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109786741129663376)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.REGEXP.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le filtre renvoie des r\00E9sultats en fonction de l''expression r\00E9guli\00E8re saisie.</p>'),
unistr('        <p>Remarque : l''utilisation d''op\00E9rateurs REGEXP est complexe et est g\00E9n\00E9ralement r\00E9serv\00E9e aux utilisateurs avanc\00E9s. De tels op\00E9rateurs peuvent entra\00EEner de tr\00E8s mauvaises performances.</p>')))
,p_version_scn=>2564597
);
