wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109669451419663341)
,p_name=>'PE.PROPERTY.HELP_TEXT.COMPONENT_PROPERTY.IG_ATTRIBUTES.HELP'
,p_message_language=>'fr'
,p_message_text=>unistr('<p>Utilisez cet attribut pour saisir le texte d''aide pour la grille interactive. Le texte d''aide saisi est affich\00E9 avec le contenu d''aide par d\00E9faut sous l''aide du menu Actions.</p>')
