,p_version_scn=>2564554
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109545090523663303)
,p_name=>'PE.PROPERTY.HTTP_METHOD.LOV.PUT.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('Sert d''ordinaire \00E0 <em>remplacer</em> une nouvelle ressource sur le serveur. Un corps de demande est g\00E9n\00E9ralement requis. Vous devez transmettre <em>tous</em> les attributs'),
unistr('au serveur. Les attributs manquants seront probablement \00E9crits sous la forme de valeurs NULL ou vides.')))
,p_version_scn=>2564554
);
