,p_name=>'PE.PROPERTY.ICON_VIEW_CUSTOM.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Saisissez le code HTML de colonne personnalis\00E9 pour la vue Ic\00F4ne.</p>'),
unistr('<p>Les cha\00EEnes de substitution suivantes sont disponibles :'),
'<ul>',
unistr('<li><code>&&lt;COLUMN_NAME&gt;.</code> : cha\00EEnes de substitution pour les noms de colonne.</li>'),
unistr('<li><code>&&lt;COLUMN_NAME&gt;_LABEL.</code> : cha\00EEnes de substitution pour les libell\00E9s de colonne.</li>'),
'<li><code>&APEX$ROW_ID.</code> : identificateur d''enregistrement de la ligne.</li>',
unistr('<li><code>&APEX$ROW_INDEX.</code> : num\00E9ro de s\00E9quence d''affichage d''enregistrement.</li>'),
unistr('<li><code>&APEX$ROW_URL.</code> : r\00E9f\00E9rence la cible de lien indiqu\00E9e.</li>'),
unistr('<li><code>&APEX$ROW_STATE_CLASSES.</code> : \00E9tat d''enregistrement tel que <code>is-inserted</code> ou <code>is-deleted</code>.</li>'),
'</ul>',
'</p>'))
,p_version_scn=>2564578
);
