,p_name=>'PE.PROPERTY.JSONCOLLECTION_POST_PROC_JS_FUNC_BODY_SQL.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('    <dl><dt>S\00E9lectionnez les colonnes EMPNO, ENAME et SAL, et filtrez toutes les lignes contenant une valeur SAL inf\00E9rieure \00E0 3 000.</dt>'),
'    <dd<dd><pre>',
'    return "select EMPNO, ENAME, SAL from #APEX$SOURCE_DATA where SAL < 3000";',
'    </pre></dd>',
'    </dl>'))
,p_version_scn=>2564424
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108689401745663045)
,p_name=>'PE.PROPERTY.JSONCOLLECTION_POST_PROC_JS_FUNC_BODY_SQL.HELP'
,p_message_language=>'fr'
,p_message_text=>unistr('Saisissez un corps de fonction JavaScript, avec lequel la requ\00EAte SQL renvoy\00E9e transforme les donn\00E9es extraites de la source Web. La requ\00EAte SQL renvoy\00E9e par le corps de fonction JavaScript doit effectuer une s\00E9lection dans la pseudo-table #APEX$SOUR')
||unistr('CE_DATA# et lire les colonnes disponibles dans le profil de donn\00E9es. La factorisation de sous-requ\00EAtes au moyen de la clause SQL WITH n''est pas prise en charge dans le cas pr\00E9sent. ')
,p_version_scn=>2564424
);
