);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108754882203663065)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.CONTENTINFO.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Un point de rep\00E8re <code>contentinfo</code> est un moyen d''identifier les informations communes en bas de chaque page de l''application, g\00E9n\00E9ralement'),
unistr('appel\00E9 "pied de page".</p>'),
unistr('<p>Les pages disposent g\00E9n\00E9ralement d''un seul point de rep\00E8re <code>contentinfo</code>. Le plus souvent pour les pages APEX, le point de rep\00E8re <code>contentinfo</code>'),
unistr('provient du mod\00E8le de page, c''est-\00E0-dire que la d\00E9finition des r\00E9gions de page en tant que r\00E9gions <code>contentinfo</code> dans APEX sera probablement rare.</p>'),
''))
,p_version_scn=>2564433
);
