wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108755097765663065)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.FORM.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Un point de rep\00E8re <code>form</code> identifie une r\00E9gion contenant un ensemble d''\00E9l\00E9ments (g\00E9n\00E9ralement des boutons et des \00E9l\00E9ments de page) qui, ensemble, sont combin\00E9s pour cr\00E9er un panneau lorsqu''aucun autre point de rep\00E8re nomm\00E9 n''est appropr')
||unistr('i\00E9 (par exemple, main ou search).</p>'),
''))
,p_version_scn=>2564433
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108755119492663065)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.MAIN.D'
,p_message_language=>'fr'
,p_message_text=>'Principal'
