wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108755218677663065)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.MAIN.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Un point de rep\00E8re <code>main</code> identifie le contenu principal de la page</p>'),
unistr('<p>Chaque page doit disposer d''un seul point de rep\00E8re <code>main</code>. Le plus souvent pour les pages APEX, le point de rep\00E8re <code>main</code>'),
unistr('provient du mod\00E8le de page, c''est-\00E0-dire qu''en g\00E9n\00E9ral, il ne sera pas n\00E9cessaire de d\00E9finir des r\00E9gions individuelles en tant que points de rep\00E8re <code>main</code>.'),
'</p>',
''))
,p_version_scn=>2564433
);
