wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108599457059663018)
,p_name=>'PE.PROPERTY.MAP_CLUSTER_POINT_FEATURE_FILL_COLOR.COMPONENT_PROPERTY.MAP_LAYER.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Veillez \00E0 ce que la couleur de remplissage des clusters de points r\00E9ponde \00E0 certains crit\00E8res de mani\00E8re \00E0 am\00E9liorer la visibilit\00E9 et l''utilisabilit\00E9 pour tous les utilisateurs.</p>'),
'<strong>Meilleures pratiques :</strong><ol>',
unistr('<li><strong>Rapport de contraste :</strong> le remplissage des clusters de points doit pr\00E9senter un rapport de contraste avec l''arri\00E8re-plan d''au moins 3:1. Les utilisateurs atteints d''une d\00E9ficience visuelle peuvent ainsi bien distinguer les points ')
||'des clusters.</li>',
unistr('<li><strong>Diff\00E9renciation avec la couleur de remplissage standard :</strong> la couleur de remplissage des clusters de points doit par ailleurs se distinguer de la couleur de remplissage standard. Cette distinction est cruciale pour que les utilisa')
||unistr('teurs distinguent ais\00E9ment les points des clusters des points de donn\00E9es standard, ce qui favorise la compr\00E9hension des donn\00E9es et les interactions.</li>'),
'</ol>',
unistr('<p>En appliquant ces r\00E8gles, nous nous effor\00E7ons de cr\00E9er une exp\00E9rience plus inclusive et accessible pour tous les utilisateurs, quelle que soit leur acuit\00E9 visuelle.</p>')))
,p_version_scn=>2564406
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110063431958663459)
,p_name=>'PE.PROPERTY.MAP_CLUSTER_POINT_FEATURE_FILL_COLOR.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Exemples des principaux codes couleur HTML :',
'<ul>',
'  <li><strong><span style="background-color: lightgray; color: black;">&nbsp;&nbsp;Noir&nbsp;&nbsp;</span></strong> <code>#000000 RGB(0,0,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: red;">&nbsp;&nbsp;Rouge&nbsp;&nbsp;</span></strong> <code>#FF0000 RGB(255,0,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: yellow;">&nbsp;&nbsp;Jaune&nbsp;&nbsp;</span></strong> <code>#FFFF00 RGB(255,255,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: lime;">&nbsp;&nbsp;Vert clair&nbsp;&nbsp;</span></strong> <code>#00FF00 RGB(0,255,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: green;">&nbsp;&nbsp;Vert&nbsp;&nbsp;</span></strong> <code>#008000 RGB(0,128,0)</code></li>',
