wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108716039407663053)
,p_name=>'PE.PROPERTY.MAP_FEATURE_FILL_COLOR.COMPONENT_PROPERTY.MAP_LAYER.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<strong>Meilleures pratiques :</strong>',
'<ul>',
unistr('<li><strong>V\00E9rification du rapport de contraste des couleurs :</strong> veillez \00E0 ce que le contraste entre la couleur de l''arri\00E8re-plan et celle du contour soit suffisant pour permettre de bien diff\00E9rencier la zone mise en \00E9vidence sur la carte. Vi')
||unistr('sez un rapport d''au moins 3:1 afin de garantir une bonne lisibilit\00E9 pour les utilisateurs, quel que soit leur niveau de d\00E9ficience visuelle. La couleur des bordures ou du contour entourant diff\00E9rentes fonctionnalit\00E9s est \00E9galement importante. Il est ')
||unistr('primordial de d\00E9finir un contraste ad\00E9quat pour que les utilisateurs puissent ais\00E9ment percevoir et discerner ces \00E9l\00E9ments visuels, ce qui am\00E9liore la lisibilit\00E9 et l''utilisabilit\00E9 globales de l''interface de carte.</li>'),
'</ul>'))
,p_version_scn=>2564427
);
