wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109386535824663255)
,p_name=>'PE.PROPERTY.REGION_DISPLAY_SELECTOR.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez <strong>Activ\00E9</strong> pour inclure cette r\00E9gion dans le s\00E9lecteur d''affichage de r\00E9gion.'),
unistr('Cet attribut est uniquement utilis\00E9 si un type de r\00E9gion de <em>s\00E9lecteur d''affichage de r\00E9gion</em> est d\00E9fini et peut \00EAtre visualis\00E9 sur la page.</p>'),
unistr('<p>Lorsqu''un utilisateur clique sur un nom de r\00E9gion inclus dans le s\00E9lecteur d''affichage de r\00E9gion, seule la r\00E9gion s\00E9lectionn\00E9e est affich\00E9e et toutes les autres r\00E9gions r\00E9pertori\00E9es sont masqu\00E9es.'),
unistr('La premi\00E8re entr\00E9e dans le s\00E9lecteur d''affichage de r\00E9gion est <em>Afficher tout</em>, qui permet \00E0 l''utilisateur d''afficher toutes les r\00E9gions disponibles, et pas uniquement la r\00E9gion pr\00E9c\00E9demment s\00E9lectionn\00E9e.</p>'),
unistr('<p>Si une r\00E9gion ne peut pas \00EAtre affich\00E9e, en fonction des conditions de r\00E9gion, elle n''est pas incluse dans les listes des r\00E9gions du s\00E9lecteur d''affichage de r\00E9gion.</p>')))
,p_version_scn=>2564532
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109386477885663255)
,p_name=>'PE.PROPERTY.REGION_DISPLAY_SELECTOR.PROMPT'
,p_message_language=>'fr'
,p_message_text=>unistr('S\00E9lecteur d''affichage de r\00E9gion')
