wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109627659634663328)
,p_name=>'PE.PROPERTY.REGION_IMAGE_URL.HELP'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Saisissez une r\00E9f\00E9rence \00E0 une URL d''image. Le contr\00F4le du positionnement des images au sein de la r\00E9gion est assur\00E9 par des mod\00E8les de r\00E9gion contenant la cha\00EEne de substitution #REGION_IMAGE# ou #REGION_IMAGE_URL#.'),
unistr('        Cette propri\00E9t\00E9 est requise si #REGION_IMAGE_URL# est utilis\00E9 dans le mod\00E8le de r\00E9gion s\00E9lectionn\00E9.')))
,p_version_scn=>2564572
);
wwv_flow_imp_shared.create_message(
