wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109442932031663272)
,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Pour renvoyer YES lorsque l''employ\00E9 est dans le service 30, entrez :</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 ? "YES" : "NO" );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564539
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109637541810663331)
,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.PROMPT'
,p_message_language=>'fr'
,p_message_text=>'Corps de fonction JavaScript'
,p_version_scn=>2564574
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109442821974663272)
,p_name=>'PE.PROPERTY.SHORTCUT_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Pour renvoyer YES lorsque l''employ\00E9 est dans le service 30, entrez :</dt>'),
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
