,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Pour r\00E9ussir le renvoi de valeurs lorsque l''employ\00E9 est dans le service 30 ou est un responsable, entrez :</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564540
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109647545219663334)
,p_name=>'PE.PROPERTY.SO_COND_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'fr'
,p_message_text=>'Expression JavaScript'
,p_version_scn=>2564575
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(109445899087663273)
,p_name=>'PE.PROPERTY.SO_COND_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Pour renvoyer des valeurs lorsque l''employ\00E9 est dans le service 30, entrez :</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 );',
