,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Les libell\00E9s de graduation peuvent \00EAtre importants pour l''accessibilit\00E9 en fonction du contexte et des besoins des utilisateurs.</p>'),
'<strong>Meilleures pratiques :</strong>',
'<ul>',
unistr('<li><strong>Compr\00E9hension contextuelle :</strong> dans certains cas, la pr\00E9sence de libell\00E9s de graduation peut fournir un contexte pr\00E9cieux ou faciliter la compr\00E9hension de la visualisation des donn\00E9es, m\00EAme pour les personnes n''\00E9tant pas atteintes ')
||unistr('d''une d\00E9ficience visuelle. Par exemple, ils peuvent aider les utilisateurs \00E0 interpr\00E9ter des tendances, \00E0 identifier des points de donn\00E9es sp\00E9cifiques ou \00E0 comprendre l''\00E9chelle de la visualisation.</li>'),
'</ul>',
unistr('<p>Les libell\00E9s de graduation peuvent jouer un r\00F4le important dans l''accessibilit\00E9, notamment pour les utilisateurs atteints d''une d\00E9ficience visuelle et ayant recours aux lecteurs d''\00E9cran.</p>')))
,p_version_scn=>2564406
);
