,p_name=>'PE.PROPERTY.TITLE_HTML_EXPR.EXAMPLES'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'  <dt>Modifier les couleurs de fond et du texte</dt>',
'    <dd><pre>&lt;span style="background-color:yellow; color:red;">&EMPLOYEE_STATUS.&lt;/span></pre></dd>',
unistr('  <dt>Utiliser l''en-t\00EAte 2</dt>'),
'    <dd><pre>&lt;h2>&EMPLOYEE_NAME.&lt;/h2></pre></dd>',
unistr('  <dt>Utiliser une classe dynamique \00E0 partir de la requ\00EAte SQL</dt>'),
'    <dd><pre>&lt;span class="&COLUMN_CLASS.">&EMPLOYEE_STATUS.&lt;/span></pre><br>',
unistr('    Les substitutions <code>&COLUMN_CLASS.</code> et <code>&EMPLOYEE_STATUS.</code> de cet exemple repr\00E9sentent des colonnes s\00E9lectionn\00E9es dans la requ\00EAte SQL d''\00E9tat.</dd>'),
'  <dt>Afficher une image et une info-bulle au passage du curseur</dt>',
'    <dd><pre>&lt;img src="&IMAGE_NAME." title="&EMPLOYEE_NAME."&gt;</pre></dd>',
'</dl>'))
,p_version_scn=>2564650
);
