,p_version_scn=>2564449
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110288672958663526)
,p_name=>'WWV_FLOW_GRID_LAYOUT.LABEL_COLUMN_SPAN_TOO_BIG'
,p_message_language=>'fr'
,p_message_text=>unistr('<p>Le libell\00E9 d''\00E9l\00E9ment de page <strong>%0</strong> ne peut pas \00EAtre affich\00E9 car le param\00E8tre de grille ColSpan de libell\00E9 pour cet \00E9l\00E9ment de page n''est pas valide. Il est d\00E9fini pour \00EAtre affich\00E9 avec le <strong>ColSpan de libell\00E9 %1</strong>. Il n')
||unistr('''est pas pris en charge car l''\00E9l\00E9ment de page lui-m\00EAme n''a que <strong>%2 colonnes</strong> disponibles.</p>')
,p_version_scn=>2564672
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108900740216663109)
,p_name=>'WWV_FLOW_GRID_LAYOUT.MORE_THAN_CALCULATED_COLUMNS'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le composant <strong>%0</strong> ne peut pas \00EAtre affich\00E9 car ses param\00E8tres de grille ne sont pas valides. Il est d\00E9fini pour \00EAtre affich\00E9 \00E0 la <strong>colonne %1</strong> avec une <span>largeur de colonne de %2</span>. Ceci n''est pas pris en cha')
||'rge car la grille sur cette page prend en charge <strong>%3 colonnes</strong> au maximum.</p>',
unistr('<p>Ce probl\00E8me est g\00E9n\00E9ralement r\00E9solu en d\00E9finissant la colonne et la largeur de colonne sur <strong>Automatique</strong> pour tous les composants.</p>')))
,p_version_scn=>2564449
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(108900805967663109)
,p_name=>'WWV_FLOW_GRID_LAYOUT.MORE_THAN_SUPPORTED_COLUMNS'
,p_message_language=>'fr'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le composant <strong>%0</strong> ne peut pas \00EAtre affich\00E9 car ses param\00E8tres de grille ne sont pas valides. Il est d\00E9fini pour \00EAtre affich\00E9 \00E0 la <strong>colonne %1</strong> avec le <strong>ColSpan %2</strong>. Ceci n''est pas pris en charge car la ')
||'grille sur cette page ne prend en charge que <strong>%3 colonnes</strong>.</p>',
unistr('<p>Ce probl\00E8me est g\00E9n\00E9ralement r\00E9solu en d\00E9finissant Colonne et ColSpan sur <strong>Automatique</strong> pour tous les composants.</p>')))
,p_version_scn=>2564449
);
