,p_prompt=>unistr('Mod\00E8le de ligne de r\00E9sultat')
,p_attribute_type=>'HTML'
,p_is_required=>true
,p_is_translatable=>true
,p_depending_on_attribute_id=>wwv_flow_imp.id(1493694522672314.4413)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_attribute_group_id=>wwv_flow_imp.id(6038497365653879)
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Exemple : mod\00E8le d''affichage de la mise en page des r\00E9sultats de recherche par d\00E9faut.</p>'),
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
'        &lt;div class="a-ResultItem-image"&gt;&lt;img src="&amp;ICON_VALUE!ATTR." alt="&amp;TITLE!ATTR." role="presentation" /&gt;&lt;/div&gt;',
'      {when CLASS/}',
'        &lt;div class="a-ResultItem-icon u-color-var"&gt;&lt;span class="fa &amp;ICON_VALUE!ATTR." aria-hidden="true"&gt;&lt;/span&gt;&lt;/div&gt;',
'    {endcase/}',
'  {endif/}',
'  &lt;div class="a-ResultsItem-content"&gt;',
'    &lt;div class="a-ResultsItem-header"&gt;',
'      {if ?LINK/}',
'        &lt;span class="a-ResultsItem-title"&gt;&lt;a href="&amp;LINK!ATTR."&gt;&amp;TITLE.&lt;/a&gt;&lt;/span&gt;',
'      {else/}',
'        &lt;span class="a-ResultsItem-title"&gt;&amp;TITLE.&lt;/span&gt;',
'      {endif/}',
'      {if ?BADGE/}&lt;span class="a-ResultsItem-badge"&gt;&amp;BADGE.&lt;/span&gt;{endif/}',
'    &lt;/div&gt;',
'    {if ?SUBTITLE/}&lt;div class="a-ResultsItem-subTitle"&gt;&amp;SUBTITLE.&lt;/div&gt;{endif/}',
'    {if ?DESCRIPTION/}&lt;div class="a-ResultsItem-description"&gt;&amp;DESCRIPTION.&lt;/div&gt;{endif/}',
'    {if ?HAS_CUSTOM_ATTRS/}',
'      &lt;div class="a-ResultsItem-attributes"&gt;',
'        {if ?CUSTOM_01/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_01.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_02/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_02.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_03/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_03.&lt;/span&gt;{endif/}',
'      &lt;/div&gt;',
'    {endif/}',
'    {if ?LAST_MODIFIED/}&lt;div class="a-ResultsItem-misc"&gt;&amp;LAST_MODIFIED.&lt;/div&gt;{endif/}',
'  &lt;/div&gt;',
'&lt;/div&gt;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Saisissez l''expression HTML permettant d''afficher une ligne de r\00E9sultat de recherche. Utilisez la syntaxe <code>&COLUMN.</code> pour afficher les valeurs de colonne de r\00E9sultat de recherche en HTML. Prend en charge les directives de mod\00E8le. Les subst')
||'itutions suivantes sont disponibles :',
'</p>',
'<dl>',
'<dt>TITLE</dt>',
'<dd>Colonne <strong>Titre</strong>.</dd>',
'<dt>SUBTITLE</dt>',
'<dd>Colonne <strong>Sous-titre</strong>.</dd>',
'<dt>PRIMARY_KEY_1</dt>',
unistr('<dd>Colonne <strong>Cl\00E9 primaire</strong>.</dd>'),
'<dt>PRIMARY_KEY_2</dt>',
unistr('<dd>Seconde colonne <strong>Cl\00E9 primaire</strong>.</dd>'),
'<dt>DESCRIPTION</dt>',
'<dd>Colonne <strong>Description</strong>.</dd>',
'<dt>BADGE</dt>',
'<dd>Colonne <strong>Badge</strong>.</dd>',
'<dt>LAST_MODIFIED</dt>',
unistr('<dd>Colonne <strong>Derni\00E8re modification</strong>. Le <strong>masque de format de derni\00E8re modification</strong> sera appliqu\00E9 \00E0 cette colonne, si indiqu\00E9.</dd>'),
'<dt>CUSTOM_01</dt>',
'<dd>Colonne <strong>Personnalisation 1</strong>.</dd>',
'<dt>CUSTOM_02</dt>',
'<dd>Colonne <strong>Personnalisation 2</strong>.</dd>',
'<dt>CUSTOM_03</dt>',
'<dd>Colonne <strong>Personnalisation 3</strong>.</dd>',
'<dt>SCORE</dt>',
unistr('<dd>Colonne <strong>Score</strong>. Pour les configurations de recherche Oracle Text, il s''agit du score renvoy\00E9 par Oracle Text. Les autres configurations permettent de mettre en correspondance une colonne de requ\00EAte.</dd>'),
'<dt>ICON_TYPE</dt>',
unistr('<dd>Repr\00E9sente le type d''ic\00F4ne : <strong>CLASS</strong>, <strong>URL</strong> ou <strong>INITIALS</strong>.</dd>'),
'<dt>ICON_VALUE</dt>',
