wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1727004690548379.4413)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758.4413)
,p_attribute_scope=>'COMPONENT'
