,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3240387001755790.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'APPLICATION'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>unistr('Param\00E8tres avanc\00E9s')
,p_attribute_type=>'TEXTAREA'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>unistr('Fournit les noms (avec distinction entre les majuscules et les minuscules) des param\00E8tres avanc\00E9s \00E0 utiliser selon les instructions du support technique Oracle, un nom de param\00E8tre par ligne.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3241072430755792.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>unistr('Utiliser l''op\00E9ration DLM en masse')
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>unistr('L''op\00E9ration DML en masse am\00E9liore les performances en regroupant plusieurs op\00E9rations de suppression, de mise \00E0 jour et d''insertion sur ce service REST en un \00E9change unique avec le serveur distant. Oracle recommande de d\00E9sactiver ce param\00E8tre uniquem')
||unistr('ent si vous rencontrez des probl\00E8mes fonctionnels avec un point d''extr\00E9mit\00E9 de service BOSS particulier lors de l''utilisation de l''op\00E9ration DML en masse.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3241422665755792.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>'Nom de la ressource racine'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_show_in_wizard=>false
,p_is_translatable=>false
,p_help_text=>unistr('Fournit le nom (avec distinction entre les majuscules et les minuscules) de la ressource de business object racine. Toutes les op\00E9rations en masse associ\00E9es \00E0 ce service REST utilisent le point d''extr\00E9mit\00E9 global de sa ressource racine. Pour un servi')
||unistr('ce REST Oracle Cloud Applications (BOSS), il s''agit g\00E9n\00E9ralement du nom du business object de niveau sup\00E9rieur comme "order", m\00EAme si le service que vous utilisez est une ressource imbriqu\00E9e, comme les \00E9l\00E9ments de ligne de "order". Par exemple, lorsq')
||unistr('ue vous utilisez une URL de point d''extr\00E9mit\00E9 de service REST telle que <code>https://example.org/api/boss/data/objects/demomodule/v1/order</code> ou une ressource imbriqu\00E9e telle que <code>https://example.org/api/boss/data/objects/demomodule/v1/orde')
||unistr('r/12345/orderlines</code>, le nom de la ressource racine est "order" dans les deux cas. Pour une nouvelle source de donn\00E9es REST, APEX d\00E9finira ce nom automatiquement mais une source de donn\00E9es REST existante peut activer les op\00E9rations DML en masse ')
||unistr('en saisissant le nom de la ressource racine appropri\00E9e.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3240624737755792.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>unistr('Utiliser le nombre total de r\00E9sultats')
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'N'
,p_is_translatable=>false
,p_help_text=>unistr('Un service REST Oracle Cloud Applications (BOSS) prend en charge le renvoi du nombre total de r\00E9sultats, m\00EAme si seul un sous-ensemble est renvoy\00E9 (par exemple, la premi\00E8re page). Dans certains cas, ce calcul du nombre total de lignes peut ajouter un')
||unistr('e surcharge d''ex\00E9cution ind\00E9sirable. Vous pouvez d\00E9sactiver l''utilisation de cette fonctionnalit\00E9 par APEX pour cette source de donn\00E9es en d\00E9finissant la valeur sur Non.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(3241860571755793.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Utiliser une pagination'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>unistr('En r\00E8gle g\00E9n\00E9rale, les services REST Oracle Cloud Applications (BOSS) prennent en charge l''extraction des r\00E9sultats page par page. Toutefois, si le point d''extr\00E9mit\00E9 de cette source de donn\00E9es ne prend pas en charge le param\00E8tre "$offset", d\00E9finissez')
||unistr(' cette propri\00E9t\00E9 sur Non afin de d\00E9sactiver la pagination.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(31645891650179321.4413)
,p_plugin_id=>wwv_flow_imp.id(3240013576755763.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_prompt=>'Type de ressource'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>false
,p_show_in_wizard=>false
,p_default_value=>'BUSINESS_OBJECT'
