unistr('<dt>Lorsque l''attribut de hi\00E9rarchie est d\00E9fini sur Non calcul\00E9</dt>'),
'<dd><pre>',
' select case when connect_by_isleaf = 1 then 0 when level = 1 then 1 else -1 end as status,',
'        level,',
