,p_version_scn=>7414340
,p_subscribe_plugin_settings=>true
,p_help_text=>unistr('Affiche un \00E9l\00E9ment dans lequel la saisie n''est pas autoris\00E9e \00E0 partir d''une expression HTML.')
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(562566479673647057.4413)
,p_plugin_id=>wwv_flow_imp.id(562560582820583985.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'html_expression'
,p_prompt=>'Expression HTML'
,p_attribute_type=>'HTML'
,p_is_required=>true
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'  <dt>Modifier les couleurs de fond et du texte</dt>',
'    <dd><pre>&lt;span style="background-color:yellow; color:red;">&amp;EMPLOYEE_STATUS.&lt;/span></pre></dd>',
unistr('  <dt>Utiliser l''en-t\00EAte 2</dt>'),
'    <dd><pre>&lt;h2>&amp;EMPLOYEE_NAME.&lt;/h2></pre></dd>',
unistr('  <dt>Utiliser une classe dynamique \00E0 partir de la requ\00EAte SQL</dt>'),
'    <dd><pre>&lt;span class="&amp;COLUMN_CLASS!ATTR.">&amp;EMPLOYEE_STATUS.&lt;/span></pre><br>',
unistr('    Les substitutions <code>&amp;COLUMN_CLASS!ATTR.</code> et <code>&amp;EMPLOYEE_STATUS.</code> de cet exemple repr\00E9sentent des colonnes s\00E9lectionn\00E9es dans la requ\00EAte SQL.</dd>'),
'  <dt>Afficher une image et une info-bulle au passage du curseur</dt>',
'    <dd><pre>&lt;img src="&amp;IMAGE_NAME!ATTR." title="&amp;EMPLOYEE_NAME!ATTR."&gt;</pre></dd>',
'</dl>'))
,p_help_text=>unistr('Entrez les expressions HTML \00E0 afficher dans cette colonne. Utilisez la syntaxe <code>&amp;COLUMN.</code> pour afficher les valeurs de colonne en HTML.')
);
end;
