wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(731386319815053643.4413)
,p_plugin_attribute_id=>wwv_flow_imp.id(964835401087640042.4413)
,p_display_sequence=>20
,p_display_value=>'Table APEX_APPLICATION_TEMP_FILES'
,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Stocke les fichiers t\00E9l\00E9charg\00E9s dans un emplacement temporaire auquel vous pouvez acc\00E9der avec la vue APEX_APPLICATION_TEMP_FILES. &PRODUCT_NAME. supprimera automatiquement les fichiers \00E0 la fin de la session ou \00E0 la fin de la demande de t\00E9l\00E9charg')
||'ement, en fonction de votre choix pour <strong>Purge du fichier</strong>.</p>',
unistr('<p>Pour acc\00E9der aux fichiers si l''option <strong>Autoriser plusieurs fichiers</strong> est d\00E9finie sur <strong>Non</strong> :</p>'),
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
unistr('<p>Pour acc\00E9der aux fichiers si l''option <strong>Autoriser plusieurs fichiers</strong> est d\00E9finie sur <strong>Oui</strong> :</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
