 p_id=>wwv_flow_imp.id(3112575602612766963.4413)
,p_plugin_id=>wwv_flow_imp.id(1630055805138100682.4413)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre><code>function(options){',
unistr('    // d\00E9sactiver la fonctionnalit\00E9 de formatage automatique '),
'    options.editorOptions.removePlugins.push( "Autoformat" );',
unistr('    // appliquer une barre d''outils personnalis\00E9e'),
'    options.editorOptions.toolbar = [ "heading", "bulletedList", "numberedList", "fontSize", "undo", "redo" ];',
'    return options;',
'}</code></pre>'))
,p_help_text=>unistr('Entrez une fonction JavaScript pour remplacer la configuration de l''\00E9diteur standard.')
);
