,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'PLSQL'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<dl><dt>Augmente de 3 % le salaire des employ\00E9s admissibles \00E0 une augmentation de salaire :</dt>'),
'<dd><pre>',
'begin',
'    for l_emp ( select empno',
'                  from emp',
'                 where deptno = :P2_DEPTNO )',
'    loop',
'        if needs_salary_raise( l_empno.empno ) then',
'            update emp',
'               set sal = sal * 1.03',
'             where empno = l_emp.empno;',
'        end if;',
'    end loop;',
'end;',
'</pre></dd>',
'</dl>',
unistr('<p>Dans cet exemple, vous devez saisir <code>P2_DEPTNO</code> dans <strong>El\00E9ments \00E0 soumettre</strong>.</p>')))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez un bloc anonyme PL/SQL en ex\00E9cution seule, qui est ex\00E9cut\00E9 sur le serveur.</p>'),
unistr('<p>Vous pouvez r\00E9f\00E9rencer d''autres \00E9l\00E9ments de page ou d''application depuis votre application \00E0 l''aide de la syntaxe Bind (par exemple <code>:P1_MY_ITEM</code>). Tout \00E9l\00E9ment r\00E9f\00E9renc\00E9 doit \00E9galement \00EAtre inclus dans l''attribut <strong>El\00E9ments de pa')
||unistr('ge \00E0 soumettre</strong>.</p>')))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(2700703882467720.4413)
,p_plugin_id=>wwv_flow_imp.id(1811565602388283608.4413)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>11
,p_prompt=>'Code JavaScript'
,p_attribute_type=>'MLE JAVASCRIPT'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(2700405449462251.4413)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'JAVASCRIPT'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<dl><dt>Augmente de 3 % le salaire des employ\00E9s admissibles \00E0 une augmentation de salaire :</dt>'),
'<dd><pre>',
'var rows;',
'function needsSalaryRaise( empno ) {',
'  // placeholder for some complicated logic to calculate if employee needs a raise',
'  return true;',
'}',
'rows = apex.conn.execute( "select empno from emp where deptno = :deptno", { deptno: apex.env.P2_DEPTNO } ).rows;',
'for ( var row of rows ) {',
'  if ( needsSalaryRaise( row.EMPNO )) {',
'    apex.conn.execute( "update emp set sal = sal * 1.03 where empno = :empno", { empno: row.EMPNO } );',
'  }',
'}',
'</pre></dd>',
'</dl>',
unistr('<p>Dans cet exemple, vous devez saisir <code>P2_DEPTNO</code> dans <strong>El\00E9ments \00E0 soumettre</strong>.</p>')))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Indiquez un bloc JavaScript en ex\00E9cution seule, qui est ex\00E9cut\00E9 sur le serveur.</p>'),
unistr('<p>Vous pouvez r\00E9f\00E9rencer d''autres \00E9l\00E9ments de page ou d''application \00E0 partir de votre application \00E0 l''aide de la syntaxe Bind (par exemple <code>apex.env.P1_MY_ITEM</code>). Tout \00E9l\00E9ment r\00E9f\00E9renc\00E9 doit \00E9galement \00EAtre inclus dans <strong>El\00E9ments de ')
||unistr('page \00E0 soumettre</strong>.</p>')))
);
